<?php
namespace App\Http\Controllers\Procurement;use App\Http\Controllers\Controller;use App\Models\{InventoryStock,StockCount,Store};use App\Services\Procurement\ProcurementService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class StockCountController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('procurement.stock-counts.index',['rows'=>StockCount::with(['store','items.inventoryItem'])->where('property_id',$p)->latest()->paginate(20),'stores'=>Store::where('property_id',$p)->where('is_active',1)->get()]);}public function store(Request $r){$d=$r->validate(['store_id'=>'required|integer','notes'=>'nullable']);$p=auth()->user()->property_id;$stocks=InventoryStock::with('item')->where('store_id',$d['store_id'])->get();DB::transaction(function()use($d,$p,$stocks){$count=StockCount::create(['property_id'=>$p,'store_id'=>$d['store_id'],'number'=>'CNT-'.now()->format('Ymd-His').'-'.random_int(10,99),'count_date'=>today(),'status'=>'counting','notes'=>$d['notes']??null,'created_by'=>auth()->id()]);foreach($stocks as $s)$count->items()->create(['inventory_item_id'=>$s->inventory_item_id,'system_quantity'=>$s->quantity,'unit_cost'=>$s->item->average_cost]);});return back()->with('success','Stock count sheet created.');}public function submit(Request $r,StockCount $stockCount,ProcurementService $svc){abort_unless($stockCount->property_id===auth()->user()->property_id,403);$d=$r->validate(['counted'=>'required|array','counted.*'=>'nullable|numeric|min:0']);foreach($d['counted'] as $id=>$qty)if($qty!==null&&$qty!=='')$stockCount->items()->whereKey($id)->update(['counted_quantity'=>$qty]);$svc->postCount($stockCount,auth()->id());return back()->with('success','Stock count posted and variances adjusted.');}}